CREATE OR REPLACE FUNCTION private.review_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.profiles;
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if tg_op = 'UPDATE' and private.is_admin() and old.user_id <> auth.uid() then
    new.id := old.id; new.work_id := old.work_id; new.user_id := old.user_id;
    new.rating := old.rating; new.body := old.body; new.author_name := old.author_name;
    new.author_avatar := old.author_avatar; new.owner := old.owner; new.created_at := old.created_at;
    new.helpful_count := old.helpful_count; new.report_count := old.report_count;
    new.reply := nullif(btrim(new.reply), '');
    new.reply_at := case when new.reply is distinct from old.reply then case when new.reply is null then null else now() end else old.reply_at end;
    new.updated_at := old.updated_at;
    return new;
  end if;
  select * into p from public.profiles where id = auth.uid();
  new.user_id := auth.uid();
  new.body := nullif(btrim(new.body), '');
  if tg_op = 'UPDATE' then new.work_id := old.work_id; end if;
  -- Stars only once the work is out.
  if not exists (select 1 from public.works w where w.id = new.work_id and w.status = 'released') then
    new.rating := null;
  end if;
  new.author_name := coalesce(nullif(btrim(p.name), ''), split_part(coalesce(auth.jwt() ->> 'email', ''), '@', 1), '');
  new.author_avatar := p.avatar_url;
  new.owner := exists (
    select 1 from public.orders o
    where o.user_id = auth.uid() and o.work_id = new.work_id and o.status in ('paid', 'processing', 'completed')
  );
  if tg_op = 'INSERT' then
    new.hidden := false; new.reply := null; new.reply_at := null;
    new.helpful_count := 0; new.report_count := 0;
    new.created_at := now();
  else
    new.created_at := old.created_at;
    new.hidden := old.hidden; new.reply := old.reply; new.reply_at := old.reply_at;
    new.helpful_count := old.helpful_count; new.report_count := old.report_count;
  end if;
  new.updated_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.zarinpal_call(test boolean, action text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  host text := case when test then 'https://sandbox.zarinpal.com' else 'https://payment.zarinpal.com' end;
  res extensions.http_response;
begin
  if action not in ('request', 'verify') then
    raise exception 'unknown action';
  end if;
  perform extensions.http_set_curlopt('CURLOPT_CONNECTTIMEOUT', '10');
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '25');
  select * into res from extensions.http((
    'POST',
    host || '/pg/v4/payment/' || action || '.json',
    array[extensions.http_header('Accept', 'application/json')],
    'application/json',
    payload::text
  )::extensions.http_request);
  begin
    return res.content::jsonb;
  exception when others then
    return jsonb_build_object('status', res.status, 'body', left(res.content, 500));
  end;
end $function$

CREATE OR REPLACE FUNCTION public.price_for(work text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.works; member bigint;
begin
  select * into w from public.works where id = work and published and price_irr is not null;
  if not found then return null; end if;
  member := case when auth.uid() is not null and private.verified() then private.member_discount(w.price_irr, auth.uid()) else 0 end;
  return jsonb_build_object('price', w.price_irr, 'member_discount', member, 'total', w.price_irr - member,
    'plan', case when member > 0 then (private.current_plan(auth.uid())).id end);
end $function$

CREATE OR REPLACE FUNCTION public.server_ip()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare res extensions.http_response;
begin
  if not private.is_admin() then raise exception 'admins only'; end if;
  perform extensions.http_set_curlopt('CURLOPT_CONNECTTIMEOUT', '10');
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '15');
  select * into res from extensions.http_get('https://checkip.amazonaws.com');
  return btrim(res.content, E' \n\r\t');
end $function$

