CREATE OR REPLACE FUNCTION private.work_alert_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare event text;
begin
  if new.status = 'released' and old.status is distinct from 'released' then event := 'released';
  elsif coalesce(new.trailer, '') <> '' and coalesce(old.trailer, '') = '' then event := 'trailer';
  else return new;
  end if;
  update public.work_alerts set pending = event, tries = 0
    where work_id = new.id
      and case when event = 'released' then released_sent_at is null else trailer_sent_at is null and released_sent_at is null end;
  if found then
    perform net.http_post(
      url := 'https://gwyqkzhhnspfadqefmix.supabase.co/functions/v1/payment',
      headers := jsonb_build_object('Content-Type', 'application/json',
        'x-retry-key', (select decrypted_secret from vault.decrypted_secrets where name = 'email_retry_key')),
      body := '{"action":"retry-emails"}'::jsonb,
      timeout_milliseconds := 60000);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.admin_remove(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then
    raise exception 'Only the owner can remove admins' using errcode = 'SF020';
  end if;
  if exists (select 1 from public.admins where user_id = p_user and role = 'owner') then
    raise exception 'The owner can''t be removed' using errcode = 'SF023';
  end if;
  delete from public.admins where user_id = p_user;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_coupon(code text, work text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.works; member bigint; q jsonb;
begin
  if auth.uid() is null or not private.verified() then return jsonb_build_object('ok', false, 'reason', 'signed_out'); end if;
  select * into w from public.works where id = work and published and price_irr is not null;
  if not found then return jsonb_build_object('ok', false, 'reason', 'other_work'); end if;
  member := private.member_discount(w.price_irr, auth.uid());
  q := private.coupon_quote(code, work, w.price_irr - member, auth.uid());
  if (q ->> 'ok')::boolean then
    q := q || jsonb_build_object('price', w.price_irr, 'member_discount', member);
  end if;
  return q;
end $function$

CREATE OR REPLACE FUNCTION private.coupon_quote(p_code text, p_work text, p_price bigint, p_user uuid, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.coupons; used integer; mine integer; discount bigint;
begin
  if p_lock then
    select * into c from public.coupons where code = upper(btrim(p_code)) for update;
  else
    select * into c from public.coupons where code = upper(btrim(p_code));
  end if;
  if not found or not c.active then return jsonb_build_object('ok', false, 'reason', 'unknown'); end if;
  if c.starts_at is not null and c.starts_at > now() then return jsonb_build_object('ok', false, 'reason', 'not_started'); end if;
  if c.ends_at is not null and c.ends_at <= now() then return jsonb_build_object('ok', false, 'reason', 'expired'); end if;
  if c.work_id is not null and c.work_id <> p_work then return jsonb_build_object('ok', false, 'reason', 'other_work'); end if;
  select count(*), count(*) filter (where user_id = p_user) into used, mine
    from public.orders where coupon_code = c.code and status <> 'cancelled';
  if c.max_uses is not null and used >= c.max_uses then return jsonb_build_object('ok', false, 'reason', 'used_up'); end if;
  if mine >= c.per_user then return jsonb_build_object('ok', false, 'reason', 'already_used'); end if;
  discount := case when c.kind = 'percent' then (p_price * c.value) / 100 else c.value end;
  -- Zarinpal's smallest payment is 10,000 Rials.
  discount := greatest(0, least(discount, p_price - 10000));
  return jsonb_build_object('ok', true, 'code', c.code, 'discount', discount, 'total', p_price - discount, 'price', p_price);
end $function$

