CREATE OR REPLACE FUNCTION private.order_plan_events()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare start timestamptz;
begin
  if new.plan_id is null or new.user_id is null then return null; end if;
  if new.status in ('paid', 'processing', 'completed') and old.status not in ('paid', 'processing', 'completed') then
    select greatest(now(), coalesce(max(ends_at), now())) into start
      from public.subscriptions where user_id = new.user_id and plan_id = new.plan_id and ends_at > now();
    insert into public.subscriptions (user_id, plan_id, order_id, starts_at, ends_at)
      values (new.user_id, new.plan_id, new.id, start, start + make_interval(days => new.plan_days))
      on conflict (order_id) do nothing;
  elsif new.status not in ('paid', 'processing', 'completed') and old.status in ('paid', 'processing', 'completed') then
    delete from public.subscriptions where order_id = new.id;
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.my_membership()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.plans; ends timestamptz;
begin
  if auth.uid() is null or not private.verified() then return null; end if;
  p := private.current_plan(auth.uid());
  if p.id is null then return null; end if;
  -- Renewals follow on, so the plan runs until the last of them ends.
  select max(ends_at) into ends from public.subscriptions where user_id = auth.uid() and plan_id = p.id and ends_at > now();
  return jsonb_build_object('plan', p.id, 'rank', p.rank, 'ends_at', ends,
    'discount_percent', p.discount_percent, 'free_kinds', to_jsonb(p.free_kinds));
end $function$

CREATE OR REPLACE FUNCTION private.order_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.works; q jsonb; p public.plans; cur public.plans; price bigint;
begin
  if tg_op = 'UPDATE' and new.user_id is null and old.user_id is not null
     and session_user not in ('authenticator', 'anon', 'authenticated') and current_setting('role', true) not in ('anon', 'authenticated') then
    new := old;
    new.user_id := null;
    new.updated_at := now();
    return new;
  end if;
  if tg_op = 'INSERT' then
    if not private.is_admin() and not coalesce((select sales_open from public.site_settings where id = 1), true) then
      raise exception 'Sales are paused' using errcode = 'SF001';
    end if;
    new.user_id := auth.uid();
    new.discount_irr := 0;
    new.member_discount_irr := 0;
    if new.plan_id is not null then
      new.plan_days := coalesce(new.plan_days, 30);
      select * into p from public.plans where id = new.plan_id and on_sale;
      select pp.price_irr into price from public.plan_prices pp where pp.plan_id = new.plan_id and pp.days = new.plan_days;
      if p.id is null or price is null then raise exception 'This plan is not on sale' using errcode = 'P0001'; end if;
      cur := private.current_plan(auth.uid());
      if cur.id is not null and cur.rank > p.rank then
        raise exception 'plan: higher' using errcode = 'SF003';
      end if;
      new.work_id := null;
      new.coupon_code := null;
      new.title := 'SauFox ' || initcap(p.id) || ' plan (' || new.plan_days || ' days)';
      new.list_amount_irr := price;
      new.amount_irr := price;
    else
      select * into w from public.works
        where id = new.work_id and published and (publish_at is null or publish_at <= now());
      if not found then raise exception 'This work is not on sale' using errcode = 'P0001'; end if;
      if w.price_irr is null then raise exception 'This work has no price yet' using errcode = 'P0001'; end if;
      new.plan_days := null;
      new.title := w.title;
      new.list_amount_irr := w.price_irr;
      new.member_discount_irr := private.member_discount(w.price_irr, auth.uid());
      if coalesce(btrim(new.coupon_code), '') <> '' then
        q := private.coupon_quote(new.coupon_code, new.work_id, w.price_irr - new.member_discount_irr, auth.uid(), true);
        if not (q ->> 'ok')::boolean then
          raise exception 'coupon: %', q ->> 'reason' using errcode = 'SF002';
        end if;
        new.coupon_code := q ->> 'code';
        new.discount_irr := (q ->> 'discount')::bigint;
      else
        new.coupon_code := null;
      end if;
      new.amount_irr := w.price_irr - new.member_discount_irr - new.discount_irr;
    end if;
    new.email := coalesce(auth.jwt() ->> 'email', '');
    new.status := 'awaiting_payment';
    new.name := btrim(new.name);
    new.created_at := now();
    new.authority := null; new.authorities := '{}'; new.ref_id := null;
    new.card_pan := null; new.paid_at := null; new.test := false;
    new.placed_email_at := null; new.paid_email_at := null;
    new.processing_email_at := null; new.completed_email_at := null;
    new.email_pending := '{}'; new.email_error := null; new.email_tries := 0;
  elsif coalesce(auth.jwt() ->> 'role', '') = 'service_role' then
    null;
  elsif not private.is_admin() then
    if not (old.status = 'awaiting_payment' and new.status = 'cancelled') then
      raise exception 'This order can''t be changed' using errcode = 'P0001';
    end if;
    new := old;
    new.status := 'cancelled';
  else
    new.id := old.id; new.number := old.number; new.user_id := old.user_id; new.work_id := old.work_id;
    new.title := old.title; new.amount_irr := old.amount_irr; new.name := old.name;
    new.email := old.email; new.phone := old.phone; new.created_at := old.created_at;
    new.authority := old.authority; new.authorities := old.authorities; new.ref_id := old.ref_id;
    new.card_pan := old.card_pan; new.test := old.test;
    new.coupon_code := old.coupon_code; new.list_amount_irr := old.list_amount_irr; new.discount_irr := old.discount_irr;
    new.plan_id := old.plan_id; new.plan_days := old.plan_days; new.member_discount_irr := old.member_discount_irr;
    new.placed_email_at := old.placed_email_at; new.paid_email_at := old.paid_email_at;
    new.processing_email_at := old.processing_email_at; new.completed_email_at := old.completed_email_at;
    new.email_pending := old.email_pending; new.email_error := old.email_error; new.email_tries := old.email_tries;
    new.paid_at := case when new.status in ('paid', 'processing', 'completed') then coalesce(old.paid_at, now()) else old.paid_at end;
  end if;
  new.updated_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.review_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.is_admin() or new.rating is not null then return new; end if;
  if exists (select 1 from public.reviews r where r.user_id = auth.uid() and r.rating is null and r.created_at > now() - interval '15 seconds') then
    raise exception 'Too fast' using errcode = 'SF004';
  end if;
  if (select count(*) from public.reviews r where r.work_id = new.work_id and r.user_id = auth.uid() and r.rating is null) >= 20 then
    raise exception 'Too many comments' using errcode = 'SF005';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.ticket_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.profiles;
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if tg_op = 'INSERT' then
    if not private.is_admin() then
      if (select count(*) from public.tickets t where t.user_id = auth.uid() and t.status <> 'closed') >= 5 then
        raise exception 'Too many open tickets' using errcode = 'SF006';
      end if;
      if exists (select 1 from public.tickets t where t.user_id = auth.uid() and t.created_at > now() - interval '1 minute') then
        raise exception 'Too fast' using errcode = 'SF004';
      end if;
    end if;
    select * into p from public.profiles where id = auth.uid();
    new.user_id := auth.uid();
    new.email := coalesce(auth.jwt() ->> 'email', '');
    new.name := coalesce(nullif(btrim(p.name), ''), split_part(new.email, '@', 1));
    new.subject := btrim(new.subject);
    if new.order_id is not null and not exists (select 1 from public.orders o where o.id = new.order_id and o.user_id = auth.uid()) then
      new.order_id := null;
    end if;
    new.status := 'open';
    new.member_unread := false;
    new.studio_unread := true;
    new.created_at := now();
    new.updated_at := now();
    new.closed_at := null;
    return new;
  end if;
  -- UPDATE
  new.id := old.id; new.number := old.number; new.user_id := old.user_id; new.email := old.email;
  new.name := old.name; new.category := old.category; new.subject := old.subject;
  new.order_id := old.order_id; new.created_at := old.created_at;
  if private.is_admin() and old.user_id <> auth.uid() then
    new.member_unread := old.member_unread;
  else
    -- The member: close it, or mark the studio's reply read.
    if new.status <> old.status and new.status <> 'closed' then new.status := old.status; end if;
    new.member_unread := old.member_unread and new.member_unread;
    new.studio_unread := old.studio_unread;
  end if;
  if new.status = 'closed' and old.status <> 'closed' then new.closed_at := now(); new.updated_at := now(); end if;
  if new.status <> 'closed' then new.closed_at := null; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.ticket_message_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tickets; p public.profiles;
begin
  select * into t from public.tickets where id = new.ticket_id;
  new.user_id := auth.uid();
  new.staff := private.is_admin() and t.user_id <> auth.uid();
  if not new.staff then
    if exists (select 1 from public.ticket_messages m where m.user_id = auth.uid() and not m.staff and m.created_at > now() - interval '10 seconds') then
      raise exception 'Too fast' using errcode = 'SF004';
    end if;
    if (select count(*) from public.ticket_messages m where m.ticket_id = t.id) >= 200 then
      raise exception 'Ticket full' using errcode = 'SF007';
    end if;
  end if;
  select * into p from public.profiles where id = auth.uid();
  new.author_name := case when new.staff then 'SauFox Entertainment'
    else coalesce(nullif(btrim(p.name), ''), split_part(coalesce(auth.jwt() ->> 'email', ''), '@', 1)) end;
  new.body := btrim(new.body);
  if new.attachment is not null and new.attachment not like t.user_id::text || '/%' then
    new.attachment := null; new.attachment_name := null;
  end if;
  new.created_at := now();
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.admin_add(p_who text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target uuid;
  hits int;
  who text := trim(coalesce(p_who, ''));
begin
  if not private.is_owner() then
    raise exception 'Only the owner can add admins' using errcode = 'SF020';
  end if;
  if position('@' in who) > 0 then
    select id into target from auth.users where lower(email) = lower(who) limit 1;
  else
    select count(*), min(id::text)::uuid into hits, target from public.profiles where lower(name) = lower(who);
    if hits > 1 then
      raise exception 'Several accounts use that name' using errcode = 'SF024';
    end if;
  end if;
  if target is null then
    raise exception 'No account found' using errcode = 'SF021';
  end if;
  if exists (select 1 from public.admins where user_id = target) then
    raise exception 'Already an admin' using errcode = 'SF022';
  end if;
  insert into public.admins (user_id, role, added_by) values (target, 'admin', auth.uid());
  return target;
end;
$function$

