$function$

CREATE OR REPLACE FUNCTION public.owner_lock(p_user uuid, p_lock boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then
    raise exception 'Only the owner can do this' using errcode = 'SF020';
  end if;
  if exists (select 1 from public.admins where user_id = p_user and role = 'owner') then
    raise exception 'Not on the owner''s account' using errcode = 'SF023';
  end if;
  update auth.users set banned_until = case when p_lock then 'infinity'::timestamptz else null end where id = p_user;
  if p_lock then
    delete from auth.sessions where user_id = p_user;
    delete from auth.refresh_tokens where user_id = p_user::text;
  end if;
end;
$function$

