CREATE OR REPLACE FUNCTION private.new_license_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  alphabet text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  part text;
  out text := 'SFOX';
  i int; j int;
begin
  for i in 1..4 loop
    part := '';
    for j in 1..4 loop
      part := part || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    out := out || '-' || part;
  end loop;
  return out;
end;
$function$

CREATE OR REPLACE FUNCTION private.order_license()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  attempt int := 0;
  is_game boolean;
begin
  if new.plan_id is not null or new.work_id is null then return new; end if;
  if new.status not in ('paid', 'processing', 'completed') then return new; end if;
  if exists (select 1 from public.licenses where order_id = new.id) then return new; end if;

  select lower(kind) = 'game' into is_game from public.works where id = new.work_id;

  loop
    begin
      insert into public.licenses (code, work_id, order_id, user_id, delivered_at)
      values (private.new_license_code(), new.work_id, new.id, new.user_id,
        case when coalesce(is_game, false) then null else now() end);
      exit;
    exception when unique_violation then
      attempt := attempt + 1;
      if attempt >= 5 then raise; end if;
    end;
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_license(p_code text)
 RETURNS TABLE(work_id text, title text, already boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  lic public.licenses;
  clean text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
begin
  if not private.verified() then
    raise exception 'Sign in first' using errcode = 'SF030';
  end if;
  select * into lic from public.licenses l
    where upper(regexp_replace(l.code, '[^A-Za-z0-9]', '', 'g')) = clean;
  if not found or lic.revoked then
    raise exception 'That key isn''t valid' using errcode = 'SF031';
  end if;
  if lic.redeemed_by is not null and lic.redeemed_by <> auth.uid() then
    raise exception 'That key is already on another account' using errcode = 'SF032';
  end if;
  if lic.redeemed_by is null then
    update public.licenses set redeemed_by = auth.uid(), redeemed_at = now(),
      delivered_at = coalesce(delivered_at, now()) where id = lic.id;
  end if;
  return query
    select w.id, w.title, (lic.redeemed_by is not null)
    from public.works w where w.id = lic.work_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_device(p_license uuid, p_device_hash text, p_device_name text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, devices integer, max_devices integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  lic public.licenses;
  used int;
  hash text := substr(regexp_replace(coalesce(p_device_hash, ''), '[^a-fA-F0-9]', '', 'g'), 1, 128);
begin
  if not private.verified() then
    raise exception 'Sign in first' using errcode = 'SF030';
  end if;
  if length(hash) < 16 then
    raise exception 'Bad device id' using errcode = 'SF033';
  end if;
  select * into lic from public.licenses l
    where l.id = p_license and not l.revoked
      and (l.redeemed_by = auth.uid() or (l.user_id = auth.uid() and l.redeemed_by is null));
  if not found then
    raise exception 'Not your license' using errcode = 'SF034';
  end if;

  -- Known device: refresh it.
  update public.license_devices
     set last_seen_at = now(), device_name = coalesce(p_device_name, device_name)
   where license_id = lic.id and device_hash = hash;
  if found then
    return query select true, (select count(*)::int from public.license_devices where license_id = lic.id), lic.max_devices;
    return;
  end if;

  select count(*) into used from public.license_devices where license_id = lic.id;
  if used >= lic.max_devices then
    return query select false, used, lic.max_devices;
    return;
  end if;
  insert into public.license_devices (license_id, device_hash, device_name)
    values (lic.id, hash, left(coalesce(p_device_name, ''), 80));
  return query select true, used + 1, lic.max_devices;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_license_delivered(p_license uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_admin() then
    raise exception 'Admins only' using errcode = 'SF020';
  end if;
  update public.licenses set delivered_at = coalesce(delivered_at, now()) where id = p_license;
end;
$function$
